// Picks the leads that are due today. Settings come from "Your Settings", rows from "Read Leads".
const s = $('Your Settings').first().json;
const ladder = String(s.followUpDays || '0,2,5,10').split(',').map(x => parseInt(String(x).trim(), 10)).filter(n => !isNaN(n) && n >= 0);
const cap = Math.max(1, Math.min(200, parseInt(s.dailyLimit, 10) || 20));
const today = $now.toFormat('yyyy-MM-dd');
const emailOk = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);
// Dates may come back as text, as a typed date, or as a spreadsheet serial number: turn all of them into YYYY-MM-DD.
const toISO = (v) => {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v === 'number') return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
  const t = String(v).trim();
  const m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  const p = Date.parse(t);
  if (isNaN(p)) return '';
  const d = new Date(p);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};
const due = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.row_number) continue;
  const email = String(r['Email'] || '').trim().toLowerCase();
  const status = String(r['Status'] || '').trim().toLowerCase();
  const step = parseInt(r['Step'], 10) || 0;
  const next = toISO(r['Next Follow-up']);
  if (!emailOk(email)) continue;
  if (!['', 'new', 'contacted'].includes(status)) continue;   // Replied, Booked, Stop and Done are left alone
  if (step >= ladder.length) continue;                          // this lead has had every email
  if (next && next > today) continue;                           // not due yet
  due.push({
    row_number: r.row_number, name: String(r['Name'] || '').trim(), email,
    interest: String(r['Interest'] || '').trim(), source: String(r['Source'] || '').trim(),
    step, totalSteps: ladder.length, isLast: step === ladder.length - 1,
    lastContacted: toISO(r['Last Contacted']), today,
    nextGapDays: step + 1 < ladder.length ? Math.max(1, ladder[step + 1] - ladder[step]) : 0,
    // what the row becomes once this email is reserved, and what it was, so a failed send can be undone
    newStep: step + 1, newStatus: step === ladder.length - 1 ? 'Done' : 'Contacted',
    nextFollowUp: step === ladder.length - 1 ? '' : $now.plus({ days: step + 1 < ladder.length ? Math.max(1, ladder[step + 1] - ladder[step]) : 0 }).toFormat('yyyy-MM-dd'),
    prevStatus: String(r['Status'] || ''), prevStep: String(r['Step'] ?? ''), prevLast: String(r['Last Contacted'] || ''), prevNext: String(r['Next Follow-up'] || ''),
  });
  if (due.length >= cap) break;
}
if (!due.length) return [];
// One inbox search covers every due lead, so Gmail is asked once per run, not once per lead.
const replyQuery = 'from:(' + due.map(d => d.email).join(' OR ') + ') newer_than:90d';
return due.map(d => ({ json: { ...d, replyQuery } }));

// Joins the inbox search to the due leads: a lead has replied if a message FROM their exact address arrived
// after we last emailed them. "STOP" style replies are treated as an opt-out.
const due = $('Pick Due Leads').all().map(i => i.json);
const msgs = $input.all().map(i => i.json).filter(m => m && Object.keys(m).length);
const addrs = (v) => ((typeof v === 'string' ? v : JSON.stringify(v || '')).toLowerCase().match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/g) || []);
const fromOf = (m) => {
  if (m.From !== undefined) return addrs(m.From);
  if (m.from !== undefined) return addrs(m.from);
  const h = ((m.payload && m.payload.headers) || []).find(x => String(x.name).toLowerCase() === 'from');
  return addrs(h ? h.value : '');
};
const timeOf = (m) => { if (m.internalDate) return Number(m.internalDate); const t = Date.parse(m.date || m.Date || ''); return isNaN(t) ? NaN : t; };
const textOf = (m) => String(m.snippet || m.text || '').replace(/\s+/g, ' ').trim();
const stopWords = /^\s*(stop|unsubscribe|remove me|opt out|opt-out)\b/i;
return due.map(l => {
  const since = l.lastContacted ? Date.parse(l.lastContacted + 'T00:00:00Z') - 86400000 : NaN;  // a day of slack for time zones
  const hits = l.step > 0 ? msgs.filter(m => fromOf(m).includes(l.email) && (isNaN(timeOf(m)) || isNaN(since) || timeOf(m) >= since)) : [];
  hits.sort((a, b) => (timeOf(b) || 0) - (timeOf(a) || 0));
  const snippet = hits[0] ? textOf(hits[0]).slice(0, 300) : '';
  return { json: { ...l, replied: hits.length > 0, optOut: hits.length > 0 && stopWords.test(snippet), replySnippet: snippet } };
});

