// Turns the AI draft (or a ready-made template when AI is off or fails) into the email, and works out what to
// write back to the sheet. Runs once per lead.
const s = $('Your Settings').first().json;
const lead = $('Match Replies').item.json;
const first = (lead.name.split(/\s+/)[0] || 'there');
const you = String(s.yourName || '').trim() || 'The team';
const biz = String(s.businessName || '').trim();
const offer = lead.interest || String(s.whatYouOffer || '').trim() || 'what you asked about';
const link = String(s.bookingLink || '').trim();
const linkLine = link ? `You can pick a time that suits you here: ${link}` : 'Just reply with a day and time that suits you.';
const T = [
  [`Thanks for reaching out, ${first}`, `Hi ${first},\n\nThanks for your interest in ${offer}. I'd love to hear a little more about what you have in mind so I can point you in the right direction.\n\nWould a quick 15-minute call this week work? ${linkLine}`],
  [`Quick follow-up, ${first}`, `Hi ${first},\n\nJust bringing this back to the top of your inbox. Are you still looking into ${offer}? I can answer any questions, no pressure at all.\n\n${linkLine}`],
  [`Still thinking about ${offer}?`, `Hi ${first},\n\nI know things get busy. If ${offer} is still on your list, I can walk you through the options in a short call.\n\n${linkLine}`],
  [`Should I close your file, ${first}?`, `Hi ${first},\n\nI haven't heard back, so I'll assume the timing isn't right and I'll stop following up. If anything changes, just reply to this email and I'll pick it up from there.`],
];
let [subject, body] = T[lead.isLast ? 3 : Math.min(lead.step, 2)];
let usedAI = false;
const ai = String($json.text || '').trim();
if (ai) {
  const clean = ai.replace(/```[a-z]*/gi, '').replace(/\*\*/g, '').trim();
  const m = clean.match(/^\s*subject\s*:\s*(.+)\r?\n([\s\S]+)$/i);
  if (m) {
    const sub = m[1].trim().replace(/^["']|["']$/g, ''), bod = m[2].trim();
    const placeholder = /\[[^\]]{2,30}\]|\{\{|\}\}/.test(sub + bod);
    if (!placeholder && sub.length >= 3 && sub.length <= 120 && bod.length >= 40 && bod.length <= 1500) { subject = sub; body = bod; usedAI = true; }
  }
}
// The AI sometimes signs off anyway: cut its sign-off so the email ends with one signature, ours.
body = body.replace(/\n\s*(best|best regards|kind regards|warm regards|regards|thanks|thank you|cheers|sincerely|talk soon)[,!.]?\s*(\n[\s\S]{0,80})?$/i, '').trim();
{                                                                       // and a closing like "Have a great week,\nSam"
  const L = body.split('\n'); while (L.length && !L[L.length - 1].trim()) L.pop();
  const last = (L[L.length - 1] || '').trim();
  if (last && last.length <= 40 && !/[.?!:]$/.test(last) && last.split(/\s+/).length <= 4) {
    let i = L.length - 2; while (i >= 0 && !L[i].trim()) i--;
    if (i >= 0 && /,\s*$/.test(L[i]) && L[i].trim().length <= 60) L.splice(i);
  }
  body = L.join('\n').trim();
}
// A blank line after the greeting, whatever the AI did.
body = body.replace(/^(\s*(hi|hello|hey|dear)\b[^\n]{0,60},)[ \t]*\n(?!\s*\n)/i, '$1\n\n');
body = body.replace(/\s*\u2014\s*/g, ', ');                         // no em dashes
const sign = `\n\nBest,\n${you}${biz ? '\n' + biz : ''}`;
const optOut = `\n\nIf you'd rather not hear from me, just reply STOP.`;
return { json: {
  row_number: lead.row_number, to: lead.email, name: lead.name, subject, body: body + sign + optOut, usedAI,
  step: lead.step, newStep: lead.step + 1, newStatus: lead.isLast ? 'Done' : 'Contacted',
  nextFollowUp: lead.isLast ? '' : $now.plus({ days: lead.nextGapDays }).toFormat('yyyy-MM-dd'), today: lead.today,
} };

// One summary email to the owner after the run: who was emailed, and which email of the ladder it was.
const sent = $('Build Email').all().map(i => i.json);
// Each item that came out of Send Email points back (pairedItem) to the email it sent.
const ok = new Set($input.all().map(i => { const p = Array.isArray(i.pairedItem) ? i.pairedItem[0] : i.pairedItem; return p ? p.item : -1; }));
const rows = sent.filter((r, idx) => ok.has(idx));
const label = (r) => r.newStatus === 'Done' ? 'last email' : (r.step === 0 ? 'first reply' : `follow-up ${r.step}`);
const lines = rows.map(r => `- ${r.name || r.to} (${r.to}): ${label(r)}${r.usedAI ? '' : ' (template)'}`);
return [{ json: {
  subject: `Lead follow-up: ${rows.length} email${rows.length === 1 ? '' : 's'} sent today`,
  body: `Your lead follow-up ran today.\n\n${lines.join('\n') || 'Nobody was due.'}\n\nLeads who reply are sent to you separately the moment the next run sees it, and their follow-ups stop.`,
} }];
